import{_ as t,o as s,c as o,a2 as a}from"./chunks/framework.BUwdTBzS.js";const g=JSON.parse('{"title":"跨项目联调 · 触发与检测","description":"","frontmatter":{"title":"跨项目联调 · 触发与检测"},"headers":[],"relativePath":"dev-flow/references/cross-project-trigger.md","filePath":"dev-flow/references/cross-project-trigger.md","lastUpdated":null}'),n={name:"dev-flow/references/cross-project-trigger.md"};function r(l,e,d,p,i,c){return s(),o("div",null,[...e[0]||(e[0]=[a(`<blockquote><p>📄 本页由源文件 <code>skills/dev-flow/references/cross-project/trigger.md</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="跨项目联调-·-触发与检测" tabindex="-1">跨项目联调 · 触发与检测 <a class="header-anchor" href="#跨项目联调-·-触发与检测" aria-label="Permalink to &quot;跨项目联调 · 触发与检测&quot;">​</a></h1><blockquote><p>父文件 → <code>references/cross-project-flow.md</code>（主流程概览 + 字段定义）。 本文件按需加载：<code>cross_project_signal_detected</code> 命中时由 step-2 加载。</p></blockquote><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>描述</th><th>示例</th></tr></thead><tbody><tr><td><strong>A→B→A（三段式）</strong></td><td>A 发现问题，根因在 B，修复 B 后回 A 安装新版本并验证</td><td>my-app 发现 bug → my-lib 修复 → my-app 安装+验证</td></tr><tr><td><strong>A→B（两段式）</strong></td><td>A 分析完成，去 B 执行修改和收尾</td><td>user-project 分析 → my-lib 修复+提交</td></tr><tr><td><strong>A→B→C→A（多段式）</strong></td><td>涉及多个上下游项目的链式修复</td><td>少见，按三段式规则递归处理</td></tr></tbody></table><h2 id="知识库平台-在跨项目联调中的特殊价值" tabindex="-1">知识库平台 在跨项目联调中的特殊价值 <a class="header-anchor" href="#知识库平台-在跨项目联调中的特殊价值" aria-label="Permalink to &quot;知识库平台 在跨项目联调中的特殊价值&quot;">​</a></h2><blockquote><p>跨项目场景下 A/B/C 项目的代码本地未必都能访问。知识库平台 全库检索是准确定位上下游消费方代码的单一可行路径。</p></blockquote><table tabindex="0"><thead><tr><th>能力</th><th>适用段</th><th>价值</th></tr></thead><tbody><tr><td><strong>消费方反查</strong></td><td>step-2 影响范围</td><td>修改 B 项目导出函数前，从 知识库平台 网罗 A/C 调用点，避免漏改</td></tr><tr><td><strong>历史类似 MR 检索</strong></td><td>step-3 制定方案</td><td>&quot;上次修改这函数时哪些消费方同时改了？&quot;——用 <code>git_merge_request</code> 查联动</td></tr><tr><td><strong>联调目标项目 profile 预检（C3）</strong></td><td>step-2 触发跨项目后</td><td>检测 B 项目 <code>_profile.md</code> 是否存在，提示是否一并 <code>dev:onboard</code></td></tr></tbody></table><h2 id="知识库平台-信号-4-强制触发" tabindex="-1">知识库平台 信号 4 强制触发 <a class="header-anchor" href="#知识库平台-信号-4-强制触发" aria-label="Permalink to &quot;知识库平台 信号 4 强制触发&quot;">​</a></h2><p>一旦 <code>cross_project.enabled=true</code>，本轮 dev-flow 的 <a href="/ai-coding-kit/dev-flow/references/remote-knowledge">remote-knowledge.md</a> §一 <strong>信号 4（cross_project_consumer_verify）必定命中</strong>：</p><ul><li><strong>调用方式</strong>：<code>data_type=[git, git_doc_platform]</code>，<strong>不传 <code>search_domain</code></strong>（全库检索，跨项目唯一场景）</li><li><strong>Token 预算</strong>：≤6000，<code>top_k=5</code>，最多 3 次 MCP 调用</li><li><strong>价值</strong>：拉取 B 项目（消费方）的使用方式与架构文档，让 A 项目改动能提前预判 B 适配点</li><li><strong>记入 step-1 JSON</strong>：<code>remote_kb_signals_hit</code> 含 <code>&quot;signal_4&quot;</code>，<code>remote_kb_calls_made ≥ 1</code></li><li><strong>降级</strong>：调用失败时本轮沉默，不阻塞跨项目流程（衔接 prompt 不依赖 MCP）</li></ul><h2 id="step-2-挂载-跨项目检测钩子" tabindex="-1">step-2 挂载：跨项目检测钩子 <a class="header-anchor" href="#step-2-挂载-跨项目检测钩子" aria-label="Permalink to &quot;step-2 挂载：跨项目检测钩子&quot;">​</a></h2><h3 id="触发条件-任一" tabindex="-1">触发条件（任一） <a class="header-anchor" href="#触发条件-任一" aria-label="Permalink to &quot;触发条件（任一）&quot;">​</a></h3><ol><li>根因定位的文件不在当前工作区目录下</li><li>修改目标是当前项目的<strong>依赖包</strong>（node_modules 中的包，需在源码仓库修改）</li><li>用户明确说&quot;需要去 XX 项目修改&quot;</li><li>分析发现问题出在上游组件库/公共包</li><li><strong><code>package.json</code> 含内部组件库依赖</strong>（隐式跨项目信号，结合需求描述判断是否影响共享逻辑）</li></ol><h3 id="检测执行" tabindex="-1">检测执行 <a class="header-anchor" href="#检测执行" aria-label="Permalink to &quot;检测执行&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>step-2 影响范围报告完成后：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 扫描文件清单中所有文件路径</span></span>
<span class="line"><span>2. 判断是否有文件不在当前 workspace 下</span></span>
<span class="line"><span>3. 判断是否有依赖包需要修改源码</span></span>
<span class="line"><span>4. 扫描 package.json dependencies，检查内部组件库依赖</span></span>
<span class="line"><span>5. 任一命中 → 触发跨项目流程 → 标记 cross_project=true</span></span></code></pre></div><h3 id="知识库平台-辅助反查-标记-cross-project-true-后立即执行" tabindex="-1">知识库平台 辅助反查（标记 cross_project=true 后立即执行） <a class="header-anchor" href="#知识库平台-辅助反查-标记-cross-project-true-后立即执行" aria-label="Permalink to &quot;知识库平台 辅助反查（标记 cross_project=true 后立即执行）&quot;">​</a></h3><p>在生成衔接 prompt 之前，必须进行一次 知识库平台 全库反查以补给影响面：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工具：    use_mcp_tool(server={remote_kb|knowledge}, tool=knowledgebase_search)</span></span>
<span class="line"><span>参数：    knowledge_uuid: your-knowledge-base-uuid</span></span>
<span class="line"><span>data_type:      git</span></span>
<span class="line"><span>query:          &quot;{待修改的导出符号/组件名/包导出路径}&quot;</span></span>
<span class="line"><span>keyword:        &quot;{中英变体 ≥3}&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 不传 search_domain → 全库检索</span></span>
<span class="line"><span>预算：    ≤2k token（top_k=5）</span></span></code></pre></div><p><strong>返回处理</strong>：</p><ul><li>命中的仓库路径 → 提取消费方项目名单，写入 <code>cross_project.consumers: [projectA, projectC]</code></li><li>消费方列表追加到影响范围表格，标签 <code>[remote-kb/git]</code></li><li><strong>命中 0 条</strong>：仅提醒&quot;未扫到其他消费方，仅修 B 项目即可&quot;，不阻塞流程</li><li>超时/失败 → 降级，提醒用户手动确认消费方列表</li></ul><h3 id="历史类似-mr-检索-b-项目-step-3-前可选" tabindex="-1">历史类似 MR 检索（B 项目 step-3 前可选） <a class="header-anchor" href="#历史类似-mr-检索-b-项目-step-3-前可选" aria-label="Permalink to &quot;历史类似 MR 检索（B 项目 step-3 前可选）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data_type: git_merge_request</span></span>
<span class="line"><span>filter:    { title: { $regex: &quot;{关键词}&quot; }, state: &quot;merged&quot; }</span></span>
<span class="line"><span>作用：     识别&quot;以前改这个函数时同时改动了哪些消费方&quot;的联动历史</span></span></code></pre></div><h3 id="触发后行为-step-2-末尾" tabindex="-1">触发后行为（step-2 末尾） <a class="header-anchor" href="#触发后行为-step-2-末尾" aria-label="Permalink to &quot;触发后行为（step-2 末尾）&quot;">​</a></h3><ol><li><strong>标记</strong>：在工作上下文 YAML 头部写入 <code>cross_project</code> 字段（详见父文件）</li><li><strong>生成 B 项目衔接 prompt</strong> → 详见 <a href="/ai-coding-kit/dev-flow/references/cross-project-handoff">handoff.md</a></li><li><strong>交互式选项</strong>（<strong>必须用 <code>ask_followup_question</code> 弹出</strong>）：</li></ol><ul><li>📋 复制衔接 prompt（去 B 项目新对话粘贴；当前流程在 step-2 暂存）</li><li>⏭️ 当前项目继续（如 monorepo 场景，不走跨项目流程）</li><li>✏️ 调整项目信息（修改 B 项目名称/路径等）</li></ul><ol><li>用户选「复制衔接 prompt」时：工作上下文 status → <code>paused_for_cross_project</code>；<code>cross_project.status = pending_fix</code>；恢复指令更新为跨项目恢复说明</li></ol>`,27)])])}const u=t(n,[["render",r]]);export{g as __pageData,u as default};
